  var c = document.getElementById('closed-host');
  var rc = c.attachShadow({ mode: 'closed' });
  rc.innerHTML = '<style>:host{display:block;padding:6px;border:1px solid #a00}</style>' +
    '<p>Inside closed shadow</p>' +
    '<button id="closed-shadow-button" type="button">Closed shadow button</button>' +
    '<input id="closed-shadow-input" type="email" name="closedmail" placeholder="closed shadow email">';

  var m = document.getElementById('mixed-host');
  var rm = m.attachShadow({ mode: 'closed' });
  rm.innerHTML = '<p>Closed shadow hosting an open child host</p><div id="inner-open-host"></div>';
  var inner = rm.querySelector('#inner-open-host');
  var ri = inner.attachShadow({ mode: 'open' });
  ri.innerHTML = '<button id="open-in-closed-button" type="button">Open inside closed</button>';
})();

